import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  createdAt: string
}

// Stand-in for a database.
const store: Post[] = []

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')

  return store
}

export async function insertPost(title: string): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    createdAt: new Date().toISOString(),
  }

  store.push(post)

  return post
}

