'use server'

import { updateTag } from 'next/cache'
import { insertPost } from '@/lib/posts'

export async function createPost(formData: FormData) {
  const title = formData.get('title')

  if (typeof title !== 'string' || title.trim() === '') {
    throw new Error('Title is required')
  }

  await insertPost(title.trim())

  // updateTag expires the "posts" tag and blocks until the invalidation is
  // in effect, so the next read of this tag is guaranteed to be fresh.
  // revalidateTag only schedules a background revalidation, which can still
  // serve stale content on the very next request.
  updateTag('posts')
}

